/**
 * Handing over the lead is its own permission. A viewer may do it only when
 * they already lead the project; the person they name must themselves be
 * allowed to update the project.
 */
export async function changeProjectLead(
  actor: Actor,
  input: ChangeProjectLeadInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:change_lead", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.leadId !== null) {
    const member = requireFound(
      await memberRepo.findMember(input.orgId, input.leadId),
      "Member",
      input.leadId,
    );
    if (member.status !== "active") {
      throw new NotFoundError("Member", input.leadId);
    }
    const candidate: Actor = {
      userId: member.userId,
      orgId: input.orgId,
      role: member.role,
    };
    if (!can(candidate, "project:update", projectResource(project))) {
      assertCan(actor, "project:update", projectResource(project));
    }
  }

  return projectRepo.updateProject({
    orgId: input.orgId,
    projectId: input.projectId,
    leadId: input.leadId,
  });
}

